'use strict';
function identityPage(){const i=W().identity;return sHead('sIdentity','S01–S04/S63/S64 · J01/J03/J28')+`<div class="form-panel">${errorBox()}<div class="work-card">${property(t('status'),esc(stateLabel(i.state)))}${property(q('Identity / membership boundary','حد الهوية والعضوية'),q('Signup alone grants no platform or academy ownership.','التسجيل وحده لا يمنح ملكية المنصة أو الأكاديمية.'))}${sButtons(btn(q('Simulate sign-in readiness','محاكاة جاهزية الدخول'),'s-identity-signin','primary'),btn(q('Recovery guidance','إرشادات الاستعادة'),'s-identity-recovery'),btn(q('No membership fixture','نموذج دون عضوية'),'s-identity-empty'),btn(q('Suspended access fixture','نموذج وصول موقوف'),'s-identity-suspend'))}</div><div class="section work-card"><h3>${q('Explicit academy and role choice','اختيار الأكاديمية والدور صراحة')}</h3><p class="subtitle">${q('One identity may hold different roles across academies. Selecting a context rechecks authority in the real application.','قد تحمل هوية واحدة أدواراً مختلفة بأكاديميات متعددة. يعيد التطبيق الفعلي فحص السلطة عند الاختيار.')}</p>${sButtons(btn('Demo A · '+q('Owner','مالك'),'s-identity-context:A'),btn('Demo B · '+q('Guardian','ولي أمر'),'s-identity-context:B'))}${property(q('Selected context','السياق المختار'),esc(i.context||'—'))}</div>${notice(q('Recovery and invitations','الاستعادة والدعوات'),q('Use the identity provider’s recovery flow; this design asks for no password or code. Business ownership recovery is separate, manually reviewed and not automatically reassigned. Invitation expiry, wrong account and revoked states are connected in Batch1.','استخدم استعادة مزود الهوية؛ لا يطلب التصميم كلمة مرور أو رمزاً. استعادة ملكية العمل منفصلة وتراجع يدوياً ولا تعاد تلقائياً. حالات الدعوة المنتهية والحساب الخاطئ والإلغاء متصلة بالدفعة الأولى.'))}${sButtons(btn(q('Profile and preferences','الملف والتفضيلات'),'nav:sPreferences'))}</div>`}
function authorityPage(){const a=W().authority;return sHead('sAuthority','S20/S21/S67 · J03/J05/J08')+sPolicy('D-003 beyond M1 / D-021',q('Fixed-role/branch-scope illustrations only; no custom delegation, new role or ownership grant.','أمثلة أدوار ثابتة ونطاق فروع فقط؛ لا تفويض مخصص أو دور جديد أو منح ملكية.'))+`<div class="form-panel">${errorBox()}<div class="work-card">${property(q('Staff profile','ملف الموظف'),'Demo Staff · STAFF-1')}${property(q('Compensation fields','حقول المستحقات'),q('Excluded from directory response','مستبعدة من استجابة الدليل'))}${property(t('status'),esc(stateLabel(a.state)))}${sField('staff-scope','Branch scope · explicit','نطاق الفرع الصريح',a.scope)}${sField('staff-reason','Action reason','سبب الإجراء')}${sConfirm('staff-review')}${sButtons(btn(q('Stage staff invitation','تهيئة دعوة موظف'),'s-staff-invite','primary'),btn(q('Review branch transfer','مراجعة نقل الفرع'),'s-staff-transfer'),btn(q('Suspend / revoke fixture','إيقاف أو إلغاء المثال'),'s-staff-revoke'),btn(q('Request ownership review','طلب مراجعة الملكية'),'s-owner-case'))}</div>${notice(q('Last-owner / sole-owner protection','حماية المالك الأخير أو الوحيد'),q('No generic staff edit transfers or removes the sole owner. Lost ownership requires evidence, review and separately approved action. No automatic recovery or impersonation.','لا ينقل تعديل موظف عام الملكية أو يزيل المالك الوحيد. فقد الملكية يحتاج دليلاً ومراجعة وإجراء معتمداً منفصلاً. لا استعادة آلية أو انتحال.'))}</div>`}
function changesPage(){const c=W().changes;return sHead('sChanges','S23–S26 · J09/J10/J11')+sPolicy('D-006/D-012/authority policy',q('Dated-session change fixture; cancellation/makeup credits, notification audience and financial recalculation remain policy-dependent.','مثال تغيير حصة مؤرخة؛ أرصدة الإلغاء والتعويض وجمهور التنبيه وإعادة الحساب تعتمد على السياسة.'))+`<div class="form-panel">${errorBox()}<div class="work-card">${property(q('Original session','الحصة الأصلية'),'SIM-SESSION · 2 Nov 2026 · 16:00–17:00 Africa/Cairo')}${property(q('Immutable history','التاريخ الثابت'),q('Attendance and posted financial history preserved','الحضور والتاريخ المالي المرحّل محفوظان'))}${property(t('status'),esc(stateLabel(c.state)))}<label class="field">${q('Change scope','نطاق التغيير')}<select id="change-scope"><option value="one">${q('This session','هذه الحصة')}</option><option value="future">${q('This and eligible future sessions','هذه والحصص اللاحقة المؤهلة')}</option></select></label>${sField('change-trainer','Replacement trainer fixture','نموذج المدرب البديل')}${sField('change-reason','Reason / conflict review','السبب ومراجعة التعارض')}${sConfirm('change-review')}${sButtons(btn(q('Preview exact affected scope','معاينة النطاق المتأثر'),'s-change-preview','primary'),btn(q('Apply reviewed substitution fixture','تطبيق الاستبدال المراجع'),'s-change-substitute'),btn(q('Propose reschedule fixture','اقتراح إعادة جدولة'),'s-change-reschedule'),btn(q('Cancel future session fixture','إلغاء الحصة المستقبلية'),'s-change-cancel'))}</div>${c.preview?notice(q('Consequence preview','معاينة النتائج'),q('Scope: ','النطاق: ')+esc(c.preview)+q('. Trainer replacement is atomic in the target contract. Notification delivery and fee/compensation effects remain independently pending. Completed sessions cannot be erased.','. استبدال المدرب ذري في العقد المقصود. التسليم وأثر الرسوم والمستحقات تبقى معلّقة منفصلة. لا محو للحصص المكتملة.')):''}${notice(q('Unavailable validation','فحص غير متاح'),q('If conflict lookup fails, no mutation may commit. The example has no live conflict query.','عند فشل فحص التعارض لا يُحفظ تعديل. المثال لا يجري فحصاً حياً.'))}</div>`}
function preferencesPage(){const p=W().preferences;return sHead('sPreferences','S04/S05/S50 · J28')+`<div class="form-panel"><div class="work-card">${property(q('Profile','الملف'),'Demo self profile · no identity mutation')}${property(q('Language / theme','اللغة والمظهر'),M.lang+' / '+M.theme)}${property(q('Optional communication preference','تفضيل تواصل اختياري'),p.channel?q('Enabled fixture','مفعّل تجريبياً'):q('Disabled fixture','معطّل تجريبياً'))}${sButtons(btn(q('Switch English / Arabic','تبديل العربية والإنجليزية'),'language'),btn(q('Switch light / dark','تبديل الفاتح والداكن'),'theme'),btn(q('Toggle optional preference','تبديل التفضيل الاختياري'),'s-pref-channel'))}</div>${sPolicy('D-014/D-015',q('Mandatory notices, quiet hours and consent are separate unresolved rules. Preference toggling sends nothing.','الإشعارات الإلزامية وأوقات الهدوء والموافقة قواعد منفصلة غير محسومة. تبديل التفضيل لا يرسل شيئاً.'))}</div>`}
function identityAction(k,v){const i=W().identity,a=W().authority,c=W().changes;if(k.startsWith('s-identity-')){if(k==='s-identity-signin')i.state='signed-in fixture · no actual authentication';else if(k==='s-identity-recovery')i.state='identity-provider recovery guidance · no code collected';else if(k==='s-identity-empty'){i.state='no membership';i.context=''}else if(k==='s-identity-suspend'){i.state='suspended · no private context';i.context=''}else if(k==='s-identity-context'){if(!i.state.startsWith('signed-in')){sError(t('restricted'));return true}i.context=v==='A'?'Demo A · Academy Owner':'Demo B · Guardian'}sSaved(sh('sIdentity'));return true}
if(k.startsWith('s-staff-')||k==='s-owner-case'){if(!sValue('staff-reason')||!sCheck('staff-review')){sError();return true}if(k==='s-staff-invite')a.state='profile exists · invitation delivery pending';else if(k==='s-staff-transfer'){if(!sValue('staff-scope')){sError();return true}a.scope=sValue('staff-scope');a.state='branch transfer fixture reviewed · history preserved'}else if(k==='s-staff-revoke')a.state='revoked fixture · new access denied';else a.state='ownership recovery case pending independent review';sSaved(sh('sAuthority'));return true}
if(k.startsWith('s-change-')){if(!sValue('change-reason')||!sCheck('change-review')){sError();return true}if(k==='s-change-preview'){c.preview=sValue('change-scope');c.state='preview ready'}else{if(c.state!=='preview ready'){sError(q('Review scope first.','راجع النطاق أولاً.'));return true}if(k==='s-change-substitute'&&!sValue('change-trainer')){sError();return true}c.state=k==='s-change-cancel'?'future cancellation fixture · historical records preserved':k==='s-change-reschedule'?'reschedule proposal · date/conflict policy unresolved':'substitution fixture · previous assignment retained in history';c.version++}sSaved(sh('sChanges'));return true}if(k==='s-pref-channel'){W().preferences.channel=!W().preferences.channel;sSaved(sh('sPreferences'));return true}return false}
const studioRoutes={studio:studioHome,sIdentity:identityPage,sAuthority:authorityPage,sChanges:changesPage,sEvaluation:evaluationPage,sProgress:progressPage,sFinance:financePage,sPay:payPage,sCommerce:commercePage,sMessages:messagesPage,sMedia:mediaPage,sSupport:supportPage,sInventory:inventoryPage,sExport:exportPage,sPrivacy:privacyPage,sServices:servicesPage,sIncident:incidentPage,sPreferences:preferencesPage};
